<?php
declare(strict_types=1);

require_once dirname(__DIR__) . '/classes/GreenPortalDatabase.php';

$env=GreenPortalDatabase::env();$legacy=GreenPortalDatabase::connect($env,'green_gd_americana','LEGADO_MODELO');$target=GreenPortalDatabase::connect($env,'ggdamericana_dbp','GPT');$target->beginTransaction();
try{
    $valid=function(string $table,string $column)use($target):array{$out=[];foreach($target->query("SELECT `$column` FROM `$table`") as $r){$v=$r[$column];if($v!==null&&$v!=='')$out[(string)$v]=true;}return $out;};
    $refs=['CODAREA'=>$valid('areas','CODAREA'),'CODATIVIDADE'=>$valid('atividades','CODATIVIDADE'),'CODASPECTO'=>$valid('aspectos','CODASPECTO'),'CODDESTINO'=>$valid('destinos','CODDESTINO'),'CODIMPACTO'=>$valid('impactos','CODIMPACTO'),'CODPERIGO'=>$valid('perigos','CODPERIGO'),'CODRISCO'=>$valid('riscos','CODRISCO'),'codunidade'=>$valid('unidades','CODUNIDADE')];
    $adjusted=[];$normalize=function(array &$row,array $columns)use(&$adjusted,$refs):void{foreach($columns as $column){$value=$row[$column]??null;if($value===null||$value==='')continue;if(!isset($refs[$column][(string)$value])){$row[$column]=null;$adjusted[$column]=($adjusted[$column]??0)+1;}}};
    $laiaCols=['CODLAIA','CODAREA','CODATIVIDADE','detalhamento','CODASPECTO','SITUACAO','TEMPORALIDADE','INFLUENCIA','CLASSIFICACAO','CODDESTINO','CODIMPACTO','ESCALA','SEVERIDADE','PROBABILIDADE_FREQUENCIA','RESULTADO','DISPOSICAOATENUANTE','FILTROB','FILTROC','FILTROD','codunidade','data_trilha','userid_trilha'];$laiaQ=implode(',',array_map(fn($c)=>"`$c`",$laiaCols));$laiaM=implode(',',array_map(fn($c)=>":l_$c",$laiaCols));$laiaU=implode(',',array_map(fn($c)=>"`$c`=VALUES(`$c`)",$laiaCols));$laiaIns=$target->prepare("INSERT INTO laia($laiaQ) VALUES($laiaM) ON DUPLICATE KEY UPDATE $laiaU");$laiaRows=$legacy->query("SELECT $laiaQ FROM laia ORDER BY CODLAIA");$laiaRead=0;$laiaSaved=0;foreach($laiaRows as $row){$normalize($row,['CODAREA','CODATIVIDADE','CODASPECTO','CODDESTINO','CODIMPACTO','codunidade']);$p=[];foreach($laiaCols as $c)$p["l_$c"]=$row[$c]??null;$laiaIns->execute($p);$laiaRead++;$laiaSaved++;}
    $lproCols=['CODLPRO','CODAREA','CODATIVIDADE','detalhamento','CODPERIGO','TIPO_DE_ATIVIDADE','SITUACAO','ABRANGENCIA','NATUREZA_DO_PERIGO','CODRISCO','SEVERIDADE','OCORRENCIA','DETECCAO','TOTAL','TOLERANCIA','ELIMINAR_RISCO','ANALISAR_SUBST_RISCO','DISPOSICAO_ATENUANTE','APLICAVEL_MEDIDAS_ENG','POSSUI_MEDIDAS_ENG','APLICAVEL_MEDIDAS_ADM','POSSUI_MEDIDAS_ADM','APLICAVEL_ADOCAO_EPIS','ADOTAR_EPIS','NECESSIDADE_NOVOS_CONTROLES','FILTROB','FILTROC','FILTROD','codunidade','dano','data_trilha','userid_trilha'];$lproQ=implode(',',array_map(fn($c)=>"`$c`",$lproCols));$lproM=implode(',',array_map(fn($c)=>":p_$c",$lproCols));$lproU=implode(',',array_map(fn($c)=>"`$c`=VALUES(`$c`)",$lproCols));$lproIns=$target->prepare("INSERT INTO lpro($lproQ) VALUES($lproM) ON DUPLICATE KEY UPDATE $lproU");$lproRows=$legacy->query("SELECT $lproQ FROM lpro ORDER BY CODLPRO");$lproRead=0;$lproSaved=0;foreach($lproRows as $row){$normalize($row,['CODAREA','CODATIVIDADE','CODPERIGO','CODRISCO','codunidade']);$p=[];foreach($lproCols as $c)$p["p_$c"]=$row[$c]??null;$lproIns->execute($p);$lproRead++;$lproSaved++;}
    $infraIns=$target->prepare('INSERT INTO ml_infraestrutura(codinfraestrutura,dscinfraestrutura) VALUES(:id,:dsc) ON DUPLICATE KEY UPDATE dscinfraestrutura=VALUES(dscinfraestrutura)');$infraRead=0;foreach($legacy->query('SELECT CODINFRAESTRUTURA,DSCINFRAESTRUTURA FROM infraestrutura ORDER BY CODINFRAESTRUTURA') as $row){$infraIns->execute(['id'=>(int)$row['CODINFRAESTRUTURA'],'dsc'=>$row['DSCINFRAESTRUTURA']]);$infraRead++;}
    $revIns=$target->prepare('INSERT INTO lais_revisao(CODREVISAO,DSCREVISAO,`DATA`) VALUES(:id,:dsc,:data) ON DUPLICATE KEY UPDATE DSCREVISAO=VALUES(DSCREVISAO),`DATA`=VALUES(`DATA`)');$revRead=0;foreach($legacy->query('SELECT CODREVISAO,DSCREVISAO,`DATA` FROM lais_revisao ORDER BY CODREVISAO') as $row){$revIns->execute(['id'=>(int)$row['CODREVISAO'],'dsc'=>$row['DSCREVISAO'],'data'=>$row['DATA']]);$revRead++;}
    $counts=['laia'=>(int)$target->query('SELECT COUNT(*) FROM laia')->fetchColumn(),'lpro'=>(int)$target->query('SELECT COUNT(*) FROM lpro')->fetchColumn(),'infraestrutura'=>(int)$target->query('SELECT COUNT(*) FROM ml_infraestrutura')->fetchColumn(),'lais_revisao'=>(int)$target->query('SELECT COUNT(*) FROM lais_revisao')->fetchColumn()];
    $sourceEmpty=['treinamentos'=>0,'monitoramentos'=>0,'controles_calibracao'=>0,'responsabilidades'=>0];$ged=[];$gedRoot='E:\\projetoGreen\\GED\\green_gd_americana';foreach(['infraestrutura','treinamentos','monitoramento','laia','lpro'] as $folder){$base=$gedRoot.DIRECTORY_SEPARATOR.$folder;$ged[$folder]=['existe'=>is_dir($base),'arquivos'=>0];if(is_dir($base))$ged[$folder]['arquivos']=count(iterator_to_array(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($base,FilesystemIterator::SKIP_DOTS))));}
    $details=json_encode(['empresa'=>'Goodyear Americana','laia_lidos'=>$laiaRead,'laia_persistidos'=>$laiaSaved,'lpro_lidos'=>$lproRead,'lpro_persistidos'=>$lproSaved,'infraestrutura_lidos'=>$infraRead,'lais_revisao_lidos'=>$revRead,'contagens_destino'=>$counts,'ajustes_referencias'=>$adjusted,'dominios_vazios_no_legado'=>$sourceEmpty,'ged'=>$ged,'arquivos'=>'nenhum arquivo movido; acesso por link legado quando existir'],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);
    $audit=$target->prepare("INSERT INTO registros_migracao(codigo_migracao,origem,destino,tipo,versao,status,quantidade_registros,iniciada_em,concluida_em,detalhes) VALUES('GREEN_GOODYEAR_DOMINIOS_LEGAIS_273','green_gd_americana.laia;lpro;infraestrutura;lais_revisao','ggdamericana_dbp.laia;lpro;ml_infraestrutura;lais_revisao','DADOS','1.0.0','CONCLUIDA',:q,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,:d) ON DUPLICATE KEY UPDATE status='CONCLUIDA',quantidade_registros=VALUES(quantidade_registros),concluida_em=CURRENT_TIMESTAMP,detalhes=VALUES(detalhes)");$audit->execute(['q'=>array_sum($counts),'d'=>$details]);$target->commit();echo json_encode(['ok'=>true,'migracao'=>273,'laia_lidos'=>$laiaRead,'lpro_lidos'=>$lproRead,'infraestrutura_lidos'=>$infraRead,'lais_revisao_lidos'=>$revRead,'contagens_destino'=>$counts,'ajustes_referencias'=>$adjusted,'ged'=>$ged,'status'=>'CONCLUIDA'],JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT).PHP_EOL;
}catch(Throwable $x){if($target->inTransaction())$target->rollBack();fwrite(STDERR,$x->getMessage().PHP_EOL);exit(1);}
